settings.liquid:
{%- comment -%}
CURVJEANS — Inline Social Proof (avatars + text on one line)
• Updated localized copy: “dames” (NL), “Damen” (DE)
• Avatars + text aligned horizontally, centered overall
• Clickable → smooth-scroll to Loox reviews
{%- endcomment -%}

<a class="cj-inline-proof" href="#pdp-reviews" aria-label="Read reviews">
  <span class="cj-inline-proof__images" aria-hidden="true">
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/customer_2.jpg?v=1761889230"
         alt=""
         class="cj-inline-proof__profile">
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/Untitled_design_39.jpg?v=1762598324"
         alt=""
         class="cj-inline-proof__profile">
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/48b6354d-2f58-4dbc-8c7f-5b9c7de3e0d3.jpg?v=1762598176"
         alt=""
         class="cj-inline-proof__profile">
  </span>
  <span class="cj-inline-proof__text" id="cj-fit-text">
   <strong>10,000+</strong> curvy girls are obsessed
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878"
         alt=""
         class="cj-inline-proof__verified">
  </span>
</a>

<style>
.cj-inline-proof {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  flex-wrap: nowrap;
  width: 100%;
  margin: 16px 0 16px;
  text-decoration: none;
  -webkit-tap-highlight-color: transparent;
}
.cj-inline-proof:active { opacity: .92; }

.cj-inline-proof__images {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.cj-inline-proof__profile {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid #fff;
  margin-right: -8px;
  box-shadow: 0 0 4px rgba(0,0,0,.08);
}
.cj-inline-proof__profile:last-child { margin-right: 0; }

.cj-inline-proof__text {
  font-size: 14px;
  line-height: 1.35;
  color: #222;
  font-weight: 500;
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  white-space: nowrap;
}
.cj-inline-proof__text strong {
  font-weight: 700;
  margin-right: 4px;
}

.cj-inline-proof__verified {
  width: 15px;
  height: 15px;
  margin-left: 6px;
  display: inline-block;
  vertical-align: middle;
}

@media (max-width: 420px) {
  .cj-inline-proof__text {
    font-size: 13px;
    white-space: normal;
    flex-wrap: wrap;
    justify-content: center;
    text-align: center;
  }
}
</style>

<script>
(function(){
  /* i18n */
  var fit = document.getElementById('cj-fit-text');
  if (fit){
    var p = location.pathname || '';
    if (p.startsWith('/nl')){
      fit.innerHTML =
        '<strong>10.000+</strong> dames vonden de perfecte fit ' +
        '<img loading="lazy" src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878" alt="" class="cj-inline-proof__verified">';
    } else if (p.startsWith('/de')){
      fit.innerHTML =
        '<strong>10.000+</strong> Damen lieben den Fit ' +
        '<img loading="lazy" src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878" alt="" class="cj-inline-proof__verified">';
    }
  }

  /* Smooth scroll to reviews */
  var targets = ['#pdp-reviews', '#looxReviews', '#loox-reviews', '#looxReviewsWidget', '.loox-widget'];
  function findReviews(){
    for (var i=0;i<targets.length;i++){ var el = document.querySelector(targets[i]); if(el) return el; }
    return null;
  }
  function stickyOffset(){
    var h=0;
    var header = document.querySelector('.shopify-section-header-sticky, .header, .site-header, header');
    var ann = document.querySelector('.announcement-bar, .shopify-section-announcement-bar');
    if (ann) h += ann.offsetHeight||0;
    if (header) h += header.offsetHeight||0;
    return Math.max(h,56);
  }
  document.addEventListener('click', function(e){
    var link = e.target.closest('.cj-inline-proof');
    if(!link) return;
    var dest = findReviews();
    if(dest){
      e.preventDefault();
      var top = dest.getBoundingClientRect().top + window.pageYOffset - stickyOffset();
      window.scrollTo({ top: top, behavior: 'smooth' });
    }
  }, {passive:false});
})();
</script>
